// Original essays; paragraph citations identify the evidence actually reviewed.
// No quotations or historical images are reproduced here.
const reviewedAt = '2026-10-26';
const p = (text, ...sourceIds) => ({ text, sourceIds });
const s = (id, title, ...paragraphs) => ({ id, title, paragraphs });
const t = (date, text, ...sourceIds) => ({ date, text, sourceIds });
const essay = (sections, timeline, sourceNote) => ({ reviewedAt, sections, timeline, sourceNote });

export const earlyEssays = {
  'point-comfort-1619': essay([
    s('atlantic-captivity', 'A voyage shaped by captivity', p('The people brought to Point Comfort in August 1619 had histories before Virginia. Many came from Ndongo, in present-day Angola, and had already endured capture and an Atlantic crossing. English privateers seized captives from a slave ship bound for Spanish America. The White Lion then carried a group to Virginia, where colonists exchanged provisions for human beings. The landing connected the colony to an existing Atlantic traffic in enslaved people.', 'arrival')),
    s('bondage-before-codification', 'Bondage before a settled slave code', p('The absence of a fully developed Virginia slave code did not mean these arrivals consented to their labor or migration. They arrived as captives and were sold. Early records do not make every individual’s legal position recoverable. Over subsequent decades, colonists and lawmakers made lifelong and hereditary bondage more explicit. Reading the landing alongside those later changes avoids treating the entire system of colonial slavery as already fixed on a single day.', 'arrival', 'virginia-law')),
    s('angela-in-the-record', 'Recovering a person from a census', p('One woman appears in the 1625 colonial census as Angelo, now generally called Angela, in the household of William Pierce at Jamestown’s New Towne. That brief record places an individual within the larger story of forced migration. It connects the Atlantic crossing to a particular household, while leaving much about her daily life unknown. A name in an administrative record is valuable evidence, but it is not a complete biography.', 'angela-site')),
    s('archaeology-and-absence', 'What archaeology can recover', p('Jamestown Rediscovery and the National Park Service investigated Pierce’s property between 2017 and 2019. They sought buildings, gardens, food remains, and household objects that could help reconstruct Angela’s surroundings. The project did not depend on finding an object that could be confidently labeled hers. Its account explains why someone forcibly transported with few belongings might remain difficult to identify through possessions. Archaeology offers context for her life without making missing testimony appear complete.', 'angela-site')),
  ], [
    t('August 1619', 'Captive Africans are brought to Point Comfort aboard the White Lion.', 'arrival'),
    t('1625', 'A colonial census records Angela in William Pierce’s household.', 'angela-site'),
    t('1662', 'Virginia makes children’s free or enslaved status follow their mother’s status.', 'virginia-law'),
  ], p('The accounts combine colonial documentation with modern interpretation. Their descriptions of the arrival vary in detail; this essay uses the supported month and avoids a precise passenger total. The archaeological account describes a household context, not Angela’s own testimony.', 'arrival', 'virginia-law', 'angela-site')),

  'virginia-hereditary-slavery': essay([
    s('a-law-about-children', 'Making bondage hereditary', p('In December 1662, Virginia’s General Assembly addressed the status of children born to Black women and English fathers. It declared that a child’s freedom or bondage would follow the mother’s condition. An enslaved woman’s child could therefore be held in slavery even if the father was free. The law turned birth into a mechanism for extending an enslaver’s control into another generation; the child did not need to be imported or individually captured.', 'virginia-1662-text')),
    s('whose-status-counted', 'Whose status counted', p('The act departed from the usual English common-law assumption that a child’s status followed the father. It also imposed increased penalties for interracial sexual relations involving Christians. Read together, these provisions show lawmakers regulating both labor status and intimate relationships. They did not give children a route to freedom through an English father. Instead, the rule protected the continuation of bondage through the mother, with profound consequences for enslaved families.', 'virginia-1662-text')),
    s('a-sequence-of-restrictions', 'A system assembled through law', p('The 1662 act belonged to a longer process. Virginia records from the 1630s show both lifetime service and Black people who obtained freedom after limited service. In 1640, John Punch received a sentence of lifetime servitude. In 1667, lawmakers declared that baptism did not release an enslaved person. These measures narrowed different possibilities for freedom. Their sequence shows that colonial racial slavery was constructed through successive decisions, rather than appearing fully formed at the first landing.', 'virginia-law')),
    s('family-history-and-proof', 'Why a mother’s status mattered later', p('The consequences of maternal status can also be seen in later freedom suits. The National Park Service’s account of Missouri litigation identifies proof that a mother was not legally enslaved as one basis for challenging a child’s bondage. Such cases required documents and witnesses, placing burdens on people already held in slavery. This later example helps explain what was at stake in laws governing inherited status: family history could become evidence in a fight over whether a person could be owned.', 'freedom-suits')),
  ], [
    t('1640', 'John Punch is sentenced to lifetime servitude in Virginia.', 'virginia-law'),
    t('December 1662', 'The General Assembly enacts the rule linking children’s status to their mothers.', 'virginia-1662-text'),
    t('1667', 'A further Virginia law states that baptism does not end bondage.', 'virginia-law'),
  ], p('The 1662 transcription comes from Hening’s published compilation of colonial statutes. It records lawmakers’ rule, not the experiences or consent of the people it governed. The Missouri material illustrates later litigation and is not evidence that Virginia’s statute operated identically everywhere.', 'virginia-1662-text', 'freedom-suits')),

  'stono-rebellion': essay([
    s('an-organized-break', 'An organized attempt to leave slavery', p('The Stono Rebellion began on September 9, 1739, in the South Carolina lowcountry. Enslaved people armed themselves and moved between plantations, attacking white slaveholders and encouraging others to join. The group grew as it traveled toward the Edisto River. This was collective action requiring coordination and weapons, not simply a series of isolated departures. Its participants attempted to force an opening out of the system that claimed ownership over their lives.', 'stono')),
    s('roads-and-weapons', 'Following the movement across the landscape', p('A surviving account written in Charleston in 1739 describes an attack on a warehouse where the rebels obtained firearms and powder. It then traces their passage by homes and a tavern onto the road leading southwest. Charleston County Public Library’s investigation uses that account alongside property and road records to examine the route. The geography matters because the rebels moved through an inhabited working landscape, gathering supplies and confronting the people and institutions that sustained slavery.', 'stono-geography')),
    s('militia-and-restriction', 'Suppression and a harsher legal response', p('A white militia confronted the growing party near the Edisto River and suppressed the uprising. The National Park Service connects slaveholders’ fear after Stono with the 1740 Negro Act, which strengthened control over Black people. The rebellion therefore belongs to two linked histories: people organizing to escape bondage, and colonial authorities expanding coercion to preserve it. Defeat did not make the effort insignificant; the legal response shows how seriously slaveholders took organized resistance.', 'stono')),
    s('a-marker-is-not-a-route', 'Reading commemorative places carefully', p('The location commemorated by a historic marker does not settle every geographic question. The library’s research distinguishes the site of Wallace’s Tavern from the still uncertain location of the warehouse where the action began. It also notes differences between an older nomination’s wording and a later marker. A responsible map can identify the Stono region without claiming that one modern point represents every stage of the rebellion or supplies a precise starting place.', 'stono-geography')),
  ], [
    t('September 9, 1739', 'An armed uprising begins in the Stono region of South Carolina.', 'stono'),
    t('September 9–10, 1739', 'The rebels move through the lowcountry and encounter armed suppression.', 'stono-geography'),
    t('1740', 'South Carolina enacts further controls over Black people after the rebellion.', 'stono'),
  ], p('The surviving narrative was written outside the rebels’ own voices. The library’s geographic research identifies uncertainty in the starting location; institutional summaries also vary in names and totals. This essay therefore avoids a definitive leader name or casualty count.', 'stono', 'stono-geography')),

  'wheatley-poems': essay([
    s('an-author-under-enslavement', 'An author working within bondage', p('Phillis Wheatley was brought from West Africa to Boston as an enslaved child in 1761. In the Wheatley household she learned to read and write and studied literature and classical languages. Poetry gave her access to a public world that slavery sought to deny her. Her work circulated before her book appeared: newspapers and pamphlets printed poems, and a tribute to the evangelist George Whitefield helped carry her reputation beyond Boston.', 'wheatley')),
    s('authorship-under-suspicion', 'The unequal burden of proving authorship', p('White readers’ disbelief in a Black woman’s literary ability became an obstacle to publication. In 1772, prominent Boston men examined her authorship and supplied an attestation that appeared with the volume. The episode reveals a racial condition imposed on her entrance into print: her poems were presented alongside white certification. The book’s existence nevertheless preserves Wheatley as a writer making choices of subject and form, rather than only as the subject of other people’s statements.', 'wheatley', 'wheatley-book')),
    s('london-and-boston', 'A book crossing the Atlantic', p('Poems on Various Subjects, Religious and Moral was printed in London in 1773. The Library of Congress catalog identifies the bookseller A. Bell and a Boston sales connection through Cox and Berry. Those publication details place the volume within an Atlantic book trade. London production and Boston distribution were part of the book’s material history, helping explain how an enslaved author in Massachusetts could reach readers beyond the colony that held her.', 'wheatley-book')),
    s('reading-the-volume', 'Reading beyond the milestone', p('The title announces a collection spanning religious and moral subjects, while the surviving edition contains introductory material as well as poems. Readers should distinguish Wheatley’s writing from the endorsements surrounding it. The Library of Congress also documents the provenance of particular copies and explicitly warns that its Jefferson exhibition copy was not Thomas Jefferson’s own. That small distinction is useful: a collection label, a later owner, and an author’s original publication are different kinds of evidence.', 'wheatley-book')),
  ], [
    t('1761', 'Wheatley arrives in Boston as an enslaved child.', 'wheatley'),
    t('1772', 'Boston men supply an attestation of her authorship.', 'wheatley'),
    t('1773', 'Her poetry collection is published in London and offered for sale in Boston.', 'wheatley-book'),
  ], p('The biography supplies life context; the Library of Congress record documents the edition and its copies. The attestation reflects racial gatekeeping and should not replace attention to Wheatley’s own authorship. Catalog provenance does not establish what every reader thought of the book.', 'wheatley', 'wheatley-book')),

  'free-african-society': essay([
    s('organizing-common-care', 'Organizing care through membership', p('Richard Allen and Absalom Jones formed Philadelphia’s Free African Society in April 1787. Its articles proposed a practical answer to sickness, bereavement, and insecurity: members would regularly contribute to a common fund. The association welcomed people across religious differences while requiring orderly conduct. It created a structure through which Black residents could sustain one another, rather than leaving assistance to occasional charity or to institutions that offered their community little help.', 'free-african-society')),
    s('rules-and-obligations', 'What mutual aid required', p('The surviving articles specify monthly contributions, a qualifying period before assistance, and support for members in need. They also address widows, children’s schooling, and apprenticeships. This was organized collective provision with rules governing eligibility, attendance, and the management of money. Its disciplinary language matters too: the society attached moral expectations to membership and aid. The document shows both the reach of its communal ambitions and the conditions placed on participation.', 'free-african-society')),
    s('care-in-an-epidemic', 'A city crisis extends the work', p('During Philadelphia’s yellow fever epidemic in 1793, members helped nurse sick residents and bury the dead. Allen and Jones coordinated with Mayor Matthew Clarkson while acting through their own community organization. The work crossed racial lines, even as a false belief that Black people were immune exposed them to particular demands and danger. Black Philadelphians became ill and died too. The emergency made visible the society’s capacity to organize difficult, essential work.', 'yellow-fever-response')),
    s('defending-the-record', 'Care did not end racial hostility', p('Public service did not protect Black workers from accusations of theft and exploitation. Allen and Jones answered these charges in a published account of the epidemic and their community’s response. Their defense joined practical care to a struggle over public memory: who would be credited, blamed, or believed. The National Park Service notes that the city’s formal rewards to volunteer committee members were not extended to the Free African Society, exposing the unequal recognition that followed shared danger.', 'yellow-fever-response')),
  ], [
    t('April 1787', 'Allen and Jones organize the Free African Society in Philadelphia.', 'free-african-society'),
    t('May 1787', 'The society’s articles specify subscriptions, assistance, and responsibilities.', 'free-african-society'),
    t('1793', 'Black Philadelphians provide nursing and burial work during the yellow fever epidemic.', 'yellow-fever-response'),
  ], p('The articles survive here through a transcription printed in an 1862 church history; NPS corrects its mistaken 1778 date to 1787. Rules express the founders’ intentions, while the epidemic history supplies evidence of later activity and the hostile reception it faced.', 'free-african-society', 'yellow-fever-response')),

  'freedoms-journal': essay([
    s('a-black-editorial-platform', 'Building a Black editorial platform', p('Samuel Cornish and John Russwurm launched Freedom’s Journal in New York on March 16, 1827. It was the first Black-owned and operated newspaper in the United States. Its weekly pages challenged a press environment in which white editors routinely represented Black people without giving them control of the account. Publication created an institution through which editors could select issues, answer prejudice, and address a dispersed readership on their own terms.', 'freedoms-journal-pbs')),
    s('news-and-everyday-life', 'A newspaper for everyday life', p('The paper combined political argument with practical information. Births, deaths, and marriages appeared beside school, job, and housing notices. Biographies of Black figures offered models of achievement; international coverage connected readers with places including Haiti and Sierra Leone. These features made the journal more than an abolitionist statement. They treated Black readers as people with families, work, educational ambitions, and an interest in events beyond the United States.', 'freedoms-journal-pbs')),
    s('claiming-editorial-authority', 'Claiming the authority to speak', p('The editors’ introductory letter made self-representation central to the project. Columbia University’s teaching material places that letter within the formation of a Black public community: the newspaper did not simply add more reports about African Americans, but asserted their authority to tell their own stories. Coverage of achievement, literature, and political argument challenged the narrow ways hostile newspapers depicted Black life. Editorial control meant deciding which concerns deserved attention and which voices readers could encounter.', 'freedoms-journal-columbia')),
    s('debating-colonization', 'Disagreement within a shared public', p('Debates about colonization also ran through the newspaper’s history. The American Colonization Society promoted removing free Black people to Africa, a proposal many Black Americans opposed. A newspaper created for Black readers could provide a forum for that dispute without eliminating differences within its audience. The journal’s place in community building should therefore not be confused with complete political agreement. Its history opens questions about belonging, emigration, citizenship, and who could claim the United States as home.', 'freedoms-journal-columbia')),
  ], [
    t('March 16, 1827', 'The first issue of Freedom’s Journal appears in New York.', 'freedoms-journal-pbs'),
    t('September 1827', 'Cornish leaves the paper and Russwurm becomes its sole editor.', 'freedoms-journal-pbs'),
    t('March 1829', 'Freedom’s Journal ends publication after two years.', 'freedoms-journal-pbs'),
  ], p('The PBS account provides publication history; Columbia’s educational material interprets the opening editorial and community context. Neither is a survey of all subscribers. Claims about the newspaper’s ambitions should not be mistaken for proof that every Black reader shared its positions.', 'freedoms-journal-pbs', 'freedoms-journal-columbia')),

  'nat-turner-rebellion': essay([
    s('religion-and-resistance', 'A rebellion against enslavement', p('Nat Turner, an enslaved preacher in Southampton County, Virginia, understood his planned uprising through religious signs and revelation. On the night of August 21–22, 1831, he and fellow insurgents began attacking white households. They sought weapons and recruits as they moved toward Jerusalem, the county seat. Their resistance targeted slavery through lethal violence; the people killed included women and children. Recognizing enslavement as the rebellion’s setting does not erase those deaths.', 'turner-revolt-ev')),
    s('defeat-and-retaliation', 'Defeat, hiding, and execution', p('Organized white resistance disrupted the insurgents’ advance, and further defeats ended the rebellion. White retaliation also killed Black people without trials. Turner avoided capture for weeks before being taken on October 30; he was tried and executed on November 11. These were different forms of violence: insurgent attacks, military suppression, extrajudicial killing, and state punishment. Keeping them distinct helps prevent a single casualty figure from flattening the sequence and the people caught within it.', 'turner-revolt-ev')),
    s('the-legislative-debate', 'Virginia debates slavery’s future', p('The rebellion prompted petitions and a major debate in Virginia’s legislature during 1831–1832. Proposals ranged from gradual emancipation to removing free Black people from the state. Even some proposals described as antislavery were tied to colonization and racial exclusion. Delegates’ arguments concerned security, property, political power, and morality. The debate demonstrates that the aftermath was not merely a policing response: lawmakers briefly confronted whether the institution itself should continue.', 'turner-debate-ev')),
    s('restriction-prevails', 'Restrictions replace emancipation', p('The House of Delegates ultimately declined to legislate an emancipation scheme in January 1832. A separate police measure restricted Black preaching and enslaved people’s attendance at nighttime religious meetings. These provisions attacked forms of assembly and religious leadership that white authorities associated with resistance. The political result preserved slavery while tightening supervision. The failed debate therefore exposes the distance between discussing the dangers of slavery and accepting the freedom and independent civic life of Black Virginians.', 'turner-debate-ev')),
  ], [
    t('August 21–22, 1831', 'Turner and his allies begin the Southampton uprising.', 'turner-revolt-ev'),
    t('November 11, 1831', 'Turner is executed after capture and trial.', 'turner-revolt-ev'),
    t('January 25, 1832', 'Virginia’s House declines to pursue an emancipation law.', 'turner-debate-ev'),
  ], p('Turner’s beliefs are known largely through Thomas R. Gray’s published account of his jail interviews. The two scholarly entries give differing death estimates, so this essay avoids an exact total. Their legislative evidence is clearer than any claim to recover every participant’s voice.', 'turner-revolt-ev', 'turner-debate-ev')),

  'tubman-escape': essay([
    s('the-danger-of-sale', 'A family threatened by sale', p('Harriet Tubman’s escape grew out of a specific danger. In 1849, she learned that she and her brothers could be sold, threatening another rupture in a family already divided by slavery. An initial departure with Ben and Henry ended when they turned back. Tubman then left again alone, traveling through Maryland and Delaware into Pennsylvania. The journey brought personal freedom while leaving people she loved exposed to the same system she had escaped.', 'tubman-underground')),
    s('knowledge-made-into-action', 'Knowledge made into action', p('Tubman’s effectiveness depended on skills developed through work and community life. She understood woods, waterways, and the night sky, and knew how free and enslaved Black people communicated. Those resources were essential to navigating unfamiliar danger. Her story is therefore also a history of learned expertise and relationships. The Underground Railroad was sustained by people making decisions, sharing information, and accepting risks; it was not a literal railroad with a fixed, guaranteed route.', 'tubman')),
    s('returning-for-others', 'Returning for family and friends', p('Over roughly a decade, Tubman repeatedly returned to Maryland to guide relatives and others out of slavery. The 1850 Fugitive Slave Act increased the danger by strengthening capture and removal procedures. Even freedom could remain precarious: in 1857 she helped her parents leave after her father, already free, faced possible arrest for assisting freedom seekers. These episodes reveal why reaching a free state could not erase family obligations or guarantee safety from the machinery of slavery.', 'tubman-underground')),
    s('freedom-as-continuing-work', 'Work that continued through war', p('Tubman’s activities expanded during the Civil War. She served the Union as a nurse, cook, scout, and spy, bringing practical knowledge and contacts into military work. After the war she also supported women’s suffrage and cared for older people in Auburn, New York. Her escape in 1849 begins this entry, but it did not end her public life. The later work connects a personal act of self-emancipation to continuing efforts to make freedom useful to other people.', 'tubman')),
  ], [
    t('1849', 'Tubman escapes from Maryland and reaches Pennsylvania.', 'tubman-underground'),
    t('1850s', 'She repeatedly returns to assist relatives and other freedom seekers.', 'tubman'),
    t('Summer 1857', 'She helps her parents leave Maryland after a threat of arrest against her father.', 'tubman-underground'),
  ], p('The National Park Service distinguishes people Tubman personally guided from those she advised; its summaries give somewhat different estimates. This essay avoids combining those categories into a precise total and uses the year of escape rather than equating her unsuccessful first departure with final freedom.', 'tubman', 'tubman-underground')),

  'dred-scott-decision': essay([
    s('a-family-seeks-freedom', 'A family uses the courts', p('Dred and Harriet Scott filed separate freedom petitions in St. Louis on April 6, 1846. Their claim rested on residence in places where slavery was prohibited, including Illinois and Wisconsin Territory. They pursued an existing legal avenue rather than beginning with a national constitutional test. For the family, the issue was whether an enslaver’s decision to take them onto free soil had already changed their legal status and that of their children.', 'scott-chronology')),
    s('victory-reversed', 'A victory undone on appeal', p('The Scotts lost an initial trial on a technical issue, then won freedom in the St. Louis circuit court in 1850. The Missouri Supreme Court reversed that judgment in 1852, departing from earlier precedents. A federal case followed and eventually reached the United States Supreme Court. This sequence matters: the final defeat was not the only judgment they received. Their struggle unfolded through multiple courts whose treatment of freedom changed as sectional conflict intensified.', 'scott-chronology')),
    s('a-ruling-beyond-one-family', 'A ruling reaching beyond the Scotts', p('On March 6, 1857, Chief Justice Roger Taney announced the Court’s decision. The majority denied federal citizenship to Black descendants of people brought to America and enslaved, including people who were themselves free. It also declared that Congress could not prohibit slavery in federal territories. The opinion thus reached beyond whether one family’s residence had made them free. It attempted to define national belonging and limit the political power to restrain slavery’s expansion.', 'dred-scott')),
    s('judgment-and-later-freedom', 'The judgment did not end the family’s story', p('The Scotts obtained freedom through manumission in May 1857, after the Court had rejected their legal claim. Harriet remained in St. Louis, working as a laundress and living until 1876. Her history prevents the case’s conventional name from making her disappear. She had sought freedom alongside Dred, and the result affected a household. Later constitutional change repudiated the decision’s citizenship rule, but the family’s own persistence belongs within the story as well.', 'harriet-scott', 'dred-scott')),
  ], [
    t('April 6, 1846', 'Dred and Harriet Scott file their freedom petitions in St. Louis.', 'scott-chronology'),
    t('March 6, 1857', 'The Supreme Court rules against Dred Scott.', 'dred-scott'),
    t('May 26, 1857', 'The Scotts are freed through manumission by Taylor Blow.', 'harriet-scott'),
  ], p('The court opinion is evidence of what the majority ruled, not an endorsement of its racial claims. The NPS chronology and Harriet Scott biography restore the earlier litigation and family context that the abbreviated case name obscures.', 'dred-scott', 'scott-chronology', 'harriet-scott')),
  'harpers-ferry-raid': essay([
    s('planning-an-armed-campaign', 'Preparing an armed challenge to slavery', p('John Brown gathered supporters at the Kennedy Farm in Maryland during the summer of 1859, preparing an attack on the federal weapons facilities at Harpers Ferry. The operation involved fundraising, acquiring weapons, studying the town, and concealing the group from neighbors. On October 16, Brown led raiders across the Potomac. Their aim was to strike against slavery through armed action, using a federal arsenal as the starting point for a much wider struggle.', 'harpers-ferry')),
    s('the-people-behind-the-raid', 'A coalition with different lives at stake', p('The participants brought different experiences of freedom and slavery. John Copeland was a free Black man who had studied at Oberlin; Shields Green had escaped enslavement; Osborne Perry Anderson worked for a newspaper in Canada. Annie and Martha Brown helped maintain the appearance of an ordinary household at the farm before returning north. These biographies widen the story beyond Brown himself. The operation depended on Black abolitionists, family labor, and networks extending beyond Virginia.', 'brown-raiders')),
    s('capture-and-defeat', 'The raid closes around the engine house', p('The raiders seized bridges and weapons facilities, took hostages, and freed people held by nearby enslavers. Local resistance then blocked escape routes. Heyward Shepherd, a free Black railroad worker, was among those killed during the violence. By October 18, U.S. Marines broke into the engine house where Brown and others were trapped. Brown’s capture ended the raid as a military operation, but the deaths included townspeople as well as people fighting against slavery.', 'harpers-ferry')),
    s('different-aftermaths', 'Execution, escape, and testimony', p('The raiders’ outcomes were not identical. Copeland and Green were captured, tried, and hanged in Charles Town. Anderson escaped through Pennsylvania to Canada and later published A Voice from Harpers Ferry. He subsequently recruited for the Union army. Those different paths matter when evaluating the raid’s memory: some participants could explain their actions afterward, while others survive chiefly through letters, trial records, and later accounts. A history centered only on Brown’s execution loses this wider human record.', 'brown-raiders')),
  ], [
    t('July 3, 1859', 'Brown arrives near Harpers Ferry and prepares a concealed base in Maryland.', 'harpers-ferry'),
    t('October 16–18, 1859', 'The abolitionist raid seizes federal facilities before armed resistance defeats it.', 'harpers-ferry'),
    t('1861', 'Survivor Osborne Perry Anderson publishes his account of the raid.', 'brown-raiders'),
  ], p('NPS supplies a reconstructed chronology and separate participant biographies. These sources support the sequence without making every raider’s motives identical. Anderson’s later account is identified as a survivor’s perspective; it is not treated here as an impartial record of everything that occurred.', 'harpers-ferry', 'brown-raiders')),

  'smalls-planter': essay([
    s('expertise-under-enslavement', 'Maritime skill under enslavement', p('Robert Smalls worked on Charleston’s waterfront in several occupations before becoming a skilled navigator. The Confederate army forced him into service aboard the Planter, a transport vessel. His experience gave him knowledge of coastal waters that the Confederacy depended on but could not fully control. The escape that followed turned this coerced expertise toward another purpose: freeing himself, fellow crew members, and family members from the people claiming ownership over them.', 'smalls-house')),
    s('passing-the-defenses', 'Passing through Confederate defenses', p('Before dawn on May 13, 1862, Smalls and fellow enslaved crew members took the Planter out of Charleston Harbor. Women and children traveled with them. Smalls wore the captain’s straw hat, and the crew gave the expected signals while passing Confederate fortifications. The plan required more than steering a ship: it depended on appearing routine long enough to get beyond guns that could destroy them. The harbor’s familiar working practices became tools for escape.', 'smalls')),
    s('reaching-the-blockade', 'Making contact with the Union fleet', p('Once past Fort Sumter, the freedom seekers raised a white sheet and approached the Union blockade. The change of signal was essential because Confederate appearance had protected them inside the harbor but could now expose them to Union fire. They delivered the vessel to U.S. forces. The escape joined a family’s pursuit of safety to a military transfer: a ship used to serve the Confederacy was now available to the forces fighting it.', 'smalls')),
    s('from-pilot-to-representative', 'Public work beyond the escape', p('Smalls continued serving the Union during the war and later entered South Carolina politics. After service in the state legislature, he served portions of five terms in the U.S. House of Representatives. His congressional work included support for coastal improvements and defense of Black constituents against disenfranchisement. The Planter episode therefore belongs within a longer career. Winning freedom opened possibilities for public action, while violent elections and efforts to suppress Black voting demonstrated how insecure political rights remained.', 'smalls-house')),
  ], [
    t('May 13, 1862', 'The Planter carries the crew and family members through Charleston Harbor to Union forces.', 'smalls'),
    t('April 14, 1865', 'Smalls pilots the Planter to Fort Sumter for the U.S. flag-raising ceremony.', 'smalls-house'),
    t('1875', 'Smalls begins service in the United States House of Representatives.', 'smalls-house'),
  ], p('The NPS narrative and House biography agree on the escape but differ in some passenger details. This essay avoids a precise total. The House biography supplies the later political career; the dramatic crossing should not be mistaken for the end of Smalls’s struggle for rights.', 'smalls', 'smalls-house')),

  'emancipation-proclamation': essay([
    s('pressure-from-freedom-seekers', 'Freedom seekers change the wartime question', p('Long before January 1863, enslaved people crossed into Union lines, refused continued bondage, and pressed for wages. Their actions forced military officers and policymakers to confront slavery in practice. The growing presence of refugees made it harder to treat the war simply as a restoration of the old Union. The Emancipation Proclamation emerged within this changing situation, alongside earlier federal measures that had begun recognizing the freedom people were already trying to claim.', 'freedoms-eve')),
    s('a-limited-war-measure', 'What the proclamation did', p('Lincoln’s final proclamation took effect on January 1, 1863. Acting as commander in chief, he declared enslaved people free in designated areas still in rebellion and pledged federal recognition and military support for that freedom. The text also authorized Black enlistment. It was a wartime executive measure with a specified geography: loyal slave states and named Union-held areas were excluded. It changed the purpose and conduct of the war without abolishing slavery everywhere in the country.', 'emancipation')),
    s('waiting-for-january', 'Anticipation on Freedom’s Eve', p('On December 31, 1862, Black communities gathered to pray and watch for the promised change. Frederick Douglass waited in Boston, while elsewhere people assessed what a new federal policy could mean amid uncertain military prospects. The gatherings gave older Watch Night religious observances an additional association with emancipation. This anticipation is part of the event’s history: the proclamation was not only a text issued in Washington, but a promise people followed, debated, and invested with hope.', 'freedoms-eve')),
    s('declaration-and-enforcement', 'Making the declaration effective', p('Freedom under the proclamation depended on the course of the war. Its reach expanded as federal forces entered the designated areas, while Black men joined the army and navy in growing numbers. Military service allowed people previously denied freedom to participate directly in slavery’s destruction. The document’s limits and its significance therefore belong together. It did not immediately end every form of bondage, but it committed the Union war effort to defending emancipation where the order applied.', 'emancipation')),
  ], [
    t('September 22, 1862', 'Lincoln issues the preliminary proclamation, announcing a January deadline.', 'emancipation'),
    t('December 31, 1862', 'Black communities gather in anticipation of emancipation.', 'freedoms-eve'),
    t('January 1, 1863', 'The final proclamation declares freedom in the specified rebellious areas.', 'emancipation'),
  ], p('The National Archives provides the final text and explains its exclusions. NPS uses contemporary testimony to describe anticipation and self-emancipation. A legal declaration, knowledge of that declaration, and the ability to enforce it were related developments rather than one simultaneous experience.', 'emancipation', 'freedoms-eve')),

  'juneteenth-1865': essay([
    s('texas-and-the-end-of-war', 'Why Texas matters to emancipation’s chronology', p('The Confederacy’s collapse did not occur everywhere on one day. Fighting continued in Texas after Robert E. Lee’s surrender in Virginia, and Edmund Kirby Smith surrendered the Trans-Mississippi command in June 1865. Federal power in Texas had previously been too limited to enforce the Emancipation Proclamation broadly. Juneteenth belongs to this uneven geography of war and liberation. It marks the extension of military authority that could challenge enslavers’ continued power over people already declared free.', 'juneteenth-origins')),
    s('general-order-three', 'The announcement in Galveston', p('On June 19, 1865, General Gordon Granger issued General Order No. 3 in Galveston. It informed Texans that enslaved people were free under the president’s proclamation. The order announced equality in personal and property rights and described a new relationship of employer and hired worker. Its surviving handwritten record is preserved by the National Archives. The document makes the announcement’s language and date available for examination, rather than leaving the event entirely to later recollection.', 'juneteenth')),
    s('freedom-and-control', 'Freedom accompanied by instructions', p('The order also advised freed people to stay where they were and work for wages, and warned against gathering at military posts. Those instructions reveal that federal officials sought to regulate the transition as well as announce liberation. Formerly enslaved people had their own priorities, including leaving places of bondage and searching for relatives. Reading the order alongside those movements exposes a tension between freedom as an official category and freedom as the ability to choose where and how to live.', 'juneteenth', 'juneteenth-origins')),
    s('making-a-day-of-memory', 'A community commemoration grows', p('Black Texans began annual commemorations in 1866, and observance later spread beyond the state. The holiday’s meaning grew from communities preserving the memory of emancipation, rather than from the original order prescribing a celebration. Texas eventually made Juneteenth a state holiday in 1980. The date continued to express both joy at slavery’s destruction and remembrance of how long freedom had been withheld. Constitutional abolition later in 1865 was a separate milestone from the Galveston announcement.', 'juneteenth', 'juneteenth-origins')),
  ], [
    t('June 2, 1865', 'Kirby Smith formally surrenders the Confederate Trans-Mississippi command.', 'juneteenth-origins'),
    t('June 19, 1865', 'General Order No. 3 announces emancipation in Galveston.', 'juneteenth'),
    t('1866', 'Black communities in Texas begin annual Juneteenth commemorations.', 'juneteenth'),
  ], p('The order records a military announcement, not every Texan’s first knowledge of emancipation. Later institutional histories describe enforcement and commemoration. The essay does not claim that every enslaved person heard the news together or that one order immediately secured equal treatment.', 'juneteenth', 'juneteenth-origins')),

  'thirteenth-amendment': essay([
    s('beyond-wartime-emancipation', 'From a war measure to constitutional abolition', p('The Emancipation Proclamation left slavery untouched in loyal slave states and excluded specified Union-controlled areas. A constitutional amendment could reach beyond those wartime boundaries. The Thirteenth Amendment therefore addressed a different problem from announcing freedom in rebellious territory: it prohibited slavery within the United States and throughout its jurisdiction. Its adoption changed the nation’s fundamental law, removing the need to locate a person within the proclamation’s particular military geography.', 'amendment-13')),
    s('the-path-to-ratification', 'Congress proposes; states ratify', p('The Senate approved an abolition amendment in April 1864, but the House initially failed to do so. Lincoln supported another effort, and the House passed it on January 31, 1865. Approval in Congress did not itself amend the Constitution. The proposal went to the states, and the required three-fourths had ratified it by December 6. Keeping those stages separate explains why the amendment has both a congressional passage date and a later date of constitutional adoption.', 'amendment-13')),
    s('scope-and-exception', 'Reading both the prohibition and its exception', p('Section 1 prohibits slavery and involuntary servitude but includes an exception for punishment following a criminal conviction. That qualification is part of the constitutional text and cannot be omitted from an account of its scope. The prohibition also reaches private individuals, not only government action. The constitutional analysis reproduced by Cornell explains this distinctive reach: the amendment directly addresses a condition one person might impose on another, rather than merely limiting the actions of a state.', 'amendment-13-analysis')),
    s('enforcement-and-remaining-barriers', 'Abolition opens another struggle', p('Section 2 gives Congress authority to enforce the amendment through legislation. Constitutional prohibition, however, did not make discrimination and coercion vanish. The Constitution Annotated describes Black Codes and forms of compelled labor through debt among the problems freed people faced. The amendment’s enforcement power consequently became a subject of continuing legislation and litigation. Its historic achievement was foundational, while the practical meaning of freedom still required disputes over contracts, property, labor, and protection against private as well as official power.', 'amendment-13-analysis')),
  ], [
    t('April 1864', 'The Senate approves the proposed abolition amendment.', 'amendment-13'),
    t('January 31, 1865', 'The House approves the proposal for submission to the states.', 'amendment-13'),
    t('December 6, 1865', 'Ratification by the required number of states makes the amendment part of the Constitution.', 'amendment-13'),
  ], p('The National Archives supplies the amendment and adoption history; the Constitution Annotated explains its legal reach. The text establishes prohibition and enforcement power, but does not by itself measure how effectively particular communities were protected from coercion after emancipation.', 'amendment-13', 'amendment-13-analysis')),

  'fourteenth-amendment': essay([
    s('citizenship-after-slavery', 'Defining citizenship after slavery', p('Abolishing slavery left urgent questions about national belonging and legal protection. The Fourteenth Amendment supplied a constitutional citizenship rule for people born or naturalized in the United States and subject to its jurisdiction. It also recognized citizenship in the state of residence. Formerly enslaved people’s membership in the political community would no longer depend on accepting the racial exclusion announced in Dred Scott. The amendment made citizenship an explicit part of the constitutional order.', 'amendment-14', 'dred-scott')),
    s('protections-against-states', 'Protections directed at state power', p('Section 1 restricts states from abridging citizens’ privileges or immunities and from denying any person due process or equal protection. The distinction between citizens and persons matters: the protections do not all use the same wording. These clauses created constitutional tools for challenging state action. They did not automatically resolve every dispute over which rights were protected or how courts should apply them. Interpretation and enforcement remained central to their practical effect.', 'amendment-14')),
    s('rebuilding-political-authority', 'Reconstruction beyond Section 1', p('The amendment also addressed representation, former officials who participated in insurrection, and the debts left by war. It provided for reduced representation when specified male citizens were denied voting rights, restricted officeholding for certain former oath-takers, and rejected Confederate debts and compensation for emancipation. These provisions linked rights to the reconstruction of political authority. The amendment was a response to the destruction of slavery and the rebellion’s aftermath, not only a general declaration of equal treatment.', 'amendment-14-senate')),
    s('ratification-and-enforcement', 'Ratification and the work left ahead', p('Congress made ratification a condition for former Confederate states to regain representation. After the required state approvals, ratification occurred on July 9, 1868; the secretary of state’s formal certification followed on July 28. Congress also received enforcement authority. These legal and political steps created a new framework, but equal protection still depended on action by lawmakers, officials, courts, and citizens. The amendment became a basis for later rights struggles because its guarantees exceeded the protection many people actually received.', 'amendment-14-senate', 'amendment-14')),
  ], [
    t('June 13, 1866', 'Congress completes passage of the proposed Fourteenth Amendment.', 'amendment-14'),
    t('July 9, 1868', 'The amendment receives the required state ratifications.', 'amendment-14-senate'),
    t('July 28, 1868', 'The secretary of state formally certifies ratification.', 'amendment-14'),
  ], p('The primary text distinguishes citizenship from protections owed to persons. Institutional summaries necessarily compress later legal developments. This essay does not imply that ratification instantly applied every Bill of Rights provision to the states or delivered equal protection in daily life.', 'amendment-14', 'amendment-14-senate')),

  'fifteenth-amendment': essay([
    s('a-specific-voting-protection', 'A specific constitutional protection', p('The Fifteenth Amendment prohibited the United States and the states from denying or restricting citizens’ voting rights because of race, color, or previous enslavement. Congress passed the proposal on February 26, 1869, and the required states ratified it on February 3, 1870. It placed a new limit on how governments could control the electorate. For Black men, it provided constitutional protection for participation that white authorities had repeatedly excluded or threatened.', 'amendment-15')),
    s('enforcement-is-part-of-the-text', 'Enforcement is part of the amendment', p('The amendment contains two sections. The first establishes the prohibition; the second authorizes Congress to enforce it through legislation. That second provision recognizes that a declared right requires institutions able to protect it. The amendment did not itself list every permitted voting qualification or prescribe a complete election system. Its language targeted specific grounds of discrimination, leaving disputes over how officials might evade those limits and how federal power should respond.', 'amendment-15')),
    s('exclusion-through-other-rules', 'Exclusion through ostensibly general rules', p('The Senate’s history emphasizes a vulnerability: states could claim to impose qualifications equally while using them to exclude Black voters. Poll taxes and literacy tests became important instruments of disenfranchisement in former Confederate states. A rule did not have to announce a racial classification in its wording to help preserve white political control. The gap between the amendment’s explicit prohibition and the practices built around it made enforcement an enduring political and legal struggle.', 'amendment-15-senate')),
    s('constitutional-rights-and-power', 'Protection without a guarantee of power', p('The Reconstruction amendments expanded constitutional protections, but their adoption did not end resistance to Black equality. The Fifteenth Amendment illustrates why voting rights cannot be understood only by reading a date on a timeline. Formal eligibility, the qualifications imposed by states, and the ability to exercise a right in practice were separate questions. The persistence of exclusion through taxes and tests helps explain why later campaigns sought enforceable access to the ballot rather than treating the 1870 promise as already fulfilled.', 'amendment-15-senate')),
  ], [
    t('February 26, 1869', 'Congress approves the Fifteenth Amendment for ratification by the states.', 'amendment-15'),
    t('February 3, 1870', 'The amendment is ratified.', 'amendment-15'),
    t('1890s', 'Former Confederate states entrench devices that disenfranchise Black voters.', 'amendment-15'),
  ], p('The amendment’s actual wording prohibits particular reasons for denying a vote; it is not a universal suffrage clause. The Senate account explains how states exploited other qualifications. Neither the amendment nor its ratification date should be read as proof of equal electoral access.', 'amendment-15', 'amendment-15-senate')),

  'hiram-revels': essay([
    s('a-life-before-the-senate', 'An educator and minister enters national office', p('Hiram Revels was born free and worked as an educator and minister before becoming a national legislator. During the Civil War, he helped raise Black regiments. He later settled in Mississippi, served in its state senate, and was chosen by the legislature to fill an unexpired U.S. Senate term. His arrival in Washington grew out of Reconstruction’s changes in political participation, but also from a career of religious, educational, and public work.', 'revels-biography', 'revels')),
    s('a-contested-seat', 'Opponents dispute his right to serve', p('Revels’s election did not ensure an uncontested welcome. Opponents argued that he could not satisfy the Constitution’s nine-year citizenship requirement because Black people had only recently been recognized as citizens. Supporters pointed to his earlier voting in Ohio. After debate, the Senate voted to seat him, and he took the oath on February 25, 1870. The dispute exposed how the legacy of racial exclusion could be used to challenge even an elected Black official’s qualifications.', 'revels')),
    s('speaking-on-georgia', 'His first speech addresses protection', p('In his March 16 speech on Georgia’s readmission, Revels acknowledged his short tenure and inexperience with Senate procedure, then explained why the issue demanded his voice. He appealed for federal protection of loyal citizens without regard to race. He also rejected the claim that Black political participation was driven by revenge against white people. The speech presented citizenship as a claim to protection and equal rights, while answering the racial fears used to resist Reconstruction.', 'revels-georgia')),
    s('representation-as-responsibility', 'Representation as an obligation to act', p('The opening of the speech is unusually revealing about what Revels thought his office required. He described himself as responsible to people whose security was being debated in the chamber and refused to let deference silence him. Read as political argument, it shows the difference between gaining admission and using a seat. Revels did not merely symbolize a change in membership; he attempted to influence the terms under which Black citizens would participate in a reconstructed South.', 'revels-georgia')),
  ], [
    t('February 25, 1870', 'Revels takes the oath as the first Black member of Congress.', 'revels'),
    t('March 16, 1870', 'He addresses the Senate on Georgia’s readmission and citizens’ protection.', 'revels-georgia'),
    t('March 1871', 'His brief Senate service ends and he returns to Mississippi.', 'revels'),
  ], p('The Senate history explains the membership dispute; the speech preserves Revels’s own argument. A speech is evidence of what he advocated, not proof that fellow senators accepted it or that his descriptions capture every Black southerner’s views.', 'revels', 'revels-georgia')),

  'wells-antilynching': essay([
    s('journalism-before-the-campaign', 'A journalist already challenging exclusion', p('Ida B. Wells was a teacher and newspaper writer before the events of 1892. In Memphis, she criticized unequal schooling and lost her teaching position in 1891. Her writing and editorial work gave her a platform for confronting racial power, but also exposed her livelihood to retaliation. The anti-lynching campaign grew from this prior commitment to public argument: she was already contesting who could describe injustice and what consequences followed for doing so.', 'wells')),
    s('the-peoples-grocery-killings', 'The murder of three Memphis grocers', p('In 1892, a white mob murdered Tom Moss, Calvin McDowell, and Will Stewart after conflict involving their grocery business and a white competitor. The men were taken from jail rather than allowed to defend themselves in court. Moss was Wells’s friend. The killings pushed her to investigate lynching more broadly and challenge the explanations offered for it. The business conflict made visible how racial violence could destroy Black economic independence as well as individual lives.', 'wells')),
    s('an-attack-on-the-press', 'Destroying a newspaper to stop its work', p('Wells’s reporting in the Memphis Free Speech provoked threats and an attack on the paper’s office, located in the Beale Street Baptist Chapel. A white mob destroyed printing equipment. The attack targeted the means of publication as well as the writer: suppressing the newspaper would prevent its arguments from reaching readers. Wells continued her campaign after leaving Memphis, showing that the destruction of a local press could force an activist’s work into a wider network.', 'wells-places')),
    s('investigation-and-organization', 'An argument carried into other public spaces', p('During the 1890s, Wells published Southern Horrors and A Red Record to expose and condemn lynching. In Chicago, she also organized for Black women’s civic participation and challenged exclusion from the 1893 World’s Columbian Exposition. These activities were connected by a struggle over who could speak and participate in public life. Her campaign combined print, investigation, clubs, and protest, making racial violence a subject that influential institutions could not simply leave to local white accounts.', 'wells-places')),
  ], [
    t('1891', 'Wells loses her Memphis teaching position after criticizing segregated schools.', 'wells'),
    t('1892', 'The murder of three grocers and destruction of her newspaper intensify her anti-lynching work.', 'wells', 'wells-places'),
    t('1893', 'She challenges Black exclusion from the World’s Columbian Exposition and organizes in Chicago.', 'wells-places'),
  ], p('The institutional biographies connect reporting, economic conflict, and organizing. They are later interpretations rather than Wells’s complete investigative files. This account avoids treating a white mob’s accusations as established facts or implying that every lynching arose from the same circumstances.', 'wells', 'wells-places')),
};

